package services.game.objects
import io.circe.{Decoder, Encoder}
import io.circe.generic.semiauto.*
final case class Adventure(id: String, name: String, role: String, difficulty: String, truth: String, seed: Long, hour: Int, place: String, health: Int, fatigue: Int, clues: List[String], events: List[String], stage: Int, sealedEnding: Boolean, npcs: List[NpcState] = NpcState.initial, quests: List[Quest] = Nil, aiEnabled: Boolean = false, dead: Boolean = false, notes: List[JournalNote] = Nil, dialogue: List[DialogueEntry] = Nil, money: Int = 10, items: List[ItemStack] = ItemStack.initial, merchantStock: List[ItemStack] = List(ItemStack("medicine",2),ItemStack("food",3),ItemStack("oil",2),ItemStack("rare_medicine",1)), mode: String = "standard", profile: Option[PlayerProfile] = None, challengeTruth: Option[ChallengeTruth] = None, companion: Option[String] = None, campSafeUntil: Int = 57, stats: Option[PlayerStats] = None, injury: Option[String] = None, aiPause: Option[AiPause] = None, pendingRecovery: Option[Recovery] = None, battle: Option[Battle] = None, minerStatus: MinerStatus = MinerStatus.missing, knownMinerStatus: MinerStatus = MinerStatus.missing, evidence: List[Evidence] = Nil, importantClues: List[Int] = Nil, generatedStages: List[Int] = Nil)
object Adventure:
  given Encoder[Adventure] = deriveEncoder
  given Decoder[Adventure] = Decoder.instance { c =>
    for
      id <- c.get[String]("id"); name <- c.get[String]("name"); role <- c.get[String]("role")
      difficulty <- c.get[String]("difficulty"); truth <- c.get[String]("truth"); seed <- c.get[Long]("seed")
      hour <- c.get[Int]("hour"); place <- c.get[String]("place"); health <- c.get[Int]("health")
      fatigue <- c.get[Int]("fatigue"); clues <- c.get[List[String]]("clues"); events <- c.get[List[String]]("events")
      stage <- c.get[Int]("stage"); sealedEnding <- c.get[Boolean]("sealedEnding")
      npcs <- c.get[Option[List[NpcState]]]("npcs"); quests <- c.get[Option[List[Quest]]]("quests"); aiEnabled <- c.get[Option[Boolean]]("aiEnabled"); dead <- c.get[Option[Boolean]]("dead"); notes <- c.get[Option[List[JournalNote]]]("notes"); dialogue <- c.get[Option[List[DialogueEntry]]]("dialogue"); money <- c.get[Option[Int]]("money"); items <- c.get[Option[List[ItemStack]]]("items"); merchantStock <- c.get[Option[List[ItemStack]]]("merchantStock"); mode <- c.get[Option[String]]("mode"); profile <- c.get[Option[PlayerProfile]]("profile"); challengeTruth <- c.get[Option[ChallengeTruth]]("challengeTruth"); companion <- c.get[Option[String]]("companion"); campSafeUntil <- c.get[Option[Int]]("campSafeUntil"); stats <- c.get[Option[PlayerStats]]("stats"); injury <- c.get[Option[String]]("injury"); aiPause <- c.get[Option[AiPause]]("aiPause"); pendingRecovery <- c.get[Option[Recovery]]("pendingRecovery"); battle <- c.get[Option[Battle]]("battle"); minerStatus <- c.get[Option[MinerStatus]]("minerStatus"); knownMinerStatus <- c.get[Option[MinerStatus]]("knownMinerStatus"); evidence <- c.get[Option[List[Evidence]]]("evidence"); importantClues <- c.get[Option[List[Int]]]("importantClues"); generatedStages <- c.get[Option[List[Int]]]("generatedStages")
    yield Adventure(id,name,role,difficulty,truth,seed,hour,place,health,fatigue,clues,events,stage,sealedEnding,npcs.getOrElse(NpcState.initial),quests.getOrElse(Nil),aiEnabled.getOrElse(false),dead.getOrElse(false),notes.getOrElse(Nil),dialogue.getOrElse(Nil),money.getOrElse(10),items.getOrElse(ItemStack.initial),merchantStock.getOrElse(List(ItemStack("medicine",2),ItemStack("food",3),ItemStack("oil",2),ItemStack("rare_medicine",1))),mode.getOrElse("standard"),profile,challengeTruth,companion,campSafeUntil.getOrElse(57),stats,injury,aiPause,pendingRecovery,battle,minerStatus.getOrElse(MinerStatus.missing),knownMinerStatus.getOrElse(MinerStatus.missing),evidence.getOrElse(clues.map(c=>Evidence.fromText(c,None))),importantClues.getOrElse(Nil),generatedStages.getOrElse(Nil))
  }
